from taf.ul.kpi_selector.utilities.kpi_logger import log_suppression
from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class CellUnlock(OperationPrototype):
    def __init__(self, bts):
        super(CellUnlock, self).__init__(bts)
        self.operation_details = {
            "Timeout": None,
            "Operation": "Cell unlock",
            "Start Point": "Cell unlock request",
            "End point": "Cell up",
            "Requirement": "-",
        }

    def get_kpi(self):
        """
        Gets kpi for cell unlock operation.
        :return: dictionary with timeout, requirement and operation description for cell unlock
        :rtype: dict
        """
        log_suppression("There was no timeout found in Gates for stream older than 23R1, "
                        "returning default timeout for cell unlock. Please, do not base Your pronto "
                        "on that value.")

        self.operation_details["Timeout"] = 60
        return self.operation_details
